/**
 * The first dependency cycle a depth-first search finds, walking tasks and
 * their dependencies in ascending name order and starting a fresh search from
 * each task not already visited.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle, from the re-entered task back to itself, or null when there is none.
 */
export function findCycle(tasks) {
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'visiting')
    stack.push(name)
    for (const dep of [...tasks.get(name).needs].sort()) {
      const depState = state.get(dep)
      if (depState === 'visiting') return [...stack.slice(stack.indexOf(dep)), dep]
      if (depState === undefined) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === undefined) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

